document.addEventListener('DOMContentLoaded',function(){const a=CompanyApp.getQueryParams(),b=a.get('companyId')||a.get('id'),c=a.get('slug'),d=document.getElementById('packages-list'),e=document.getElementById('pkg-search');let f=[],g=null,h='';if(!b&&!c){window.location.href='./';return}CompanyApp.fetchData(i=>{const j=i.companies||[];g=j.find(k=>(b&&String(k.id)===String(b))||(c&&k.slug===c));if(!g){CompanyApp.showToast('عذراً، الشركة غير موجودة');setTimeout(()=>{window.location.href='./'},1500);return}setupCompanyHeader(g);const k=i.packages||[];f=k.filter(l=>String(l.companyId)===String(g.id));updateSEOAndSchema(g,f);renderPackages(f)},i=>showError(i));function setupCompanyHeader(j){const k=j.arName||j.name||'الشركة',l=j.slug?`details?slug=${encodeURIComponent(j.slug)}`:`details?id=${encodeURIComponent(j.id)}`;document.getElementById('page-heading').textContent=`باقات وعروض ${k}`;document.getElementById('breadcrumb-company-link').textContent=k;document.getElementById('breadcrumb-company-link').href=l;document.getElementById('btn-back-company').href=l;if(j.logo){const m=document.getElementById('comp-badge-logo');m.src=j.logo;m.alt=k;m.style.display='inline-block'}}let i;e.addEventListener('input',function(){clearTimeout(i);i=setTimeout(()=>{h=e.value.trim().toLowerCase();applyFilter()},150)});function applyFilter(){let n=f;if(h){n=f.filter(o=>{const p=(o.arTitle||o.title||'').toLowerCase(),q=(o.duration||'').toLowerCase(),r=(o.codeActivate||'').toLowerCase(),s=String(o.price||'');return p.includes(h)||q.includes(h)||r.includes(h)||s.includes(h)})}renderPackages(n)}function renderPackages(o){d.innerHTML='';if(o.length===0){d.innerHTML='<div class="col-12" style="grid-column: 1 / -1;"><div class="empty-state"><i class="fa-solid fa-box-open fa-3x"></i><h4>لا توجد باقات متوفرة حالياً</h4><p class="text-muted">لم يتم العثور على أي باقات مطابقة لعملية البحث.</p></div></div>';return}o.forEach(q=>{const r=q.arTitle||q.title||'باقة إنترنت',s=Number(q.price||0).toLocaleString(),t=q.duration?`صلاحية ${q.duration}`:'صلاحية محددة',u=q.codeActivate||'-',v=encodeURIComponent(u),w=document.createElement('div');w.className='pkg-card';w.innerHTML=`<div class="pkg-title">${r}</div><div class="pkg-price-wrap"><div class="pkg-price">${s}</div><span class="pkg-currency">ريال يمني</span></div><div class="pkg-duration"><i class="fa-regular fa-calendar-check"></i> ${t}</div><div class="activate-box"><span class="activate-label">كود تفعيل الباقة المباشر</span><div class="code-action-row"><span class="activate-code">${u}</span><div class="actions-btn-group"><button class="btn-act" onclick="copyText('${u}')" title="نسخ الكود"><i class="fa-regular fa-copy"></i> نسخ</button>${u!=='-'?`<a href="tel:${v}" class="btn-act" title="طلب الكود فوراً"><i class="fa-solid fa-phone"></i> اتصال</a>`:''}</div></div></div>`;d.appendChild(w)})}function updateSEOAndSchema(j,o){const k=j.arName||j.name||'الشركة',y=`باقات وعروض ${k} - الأسعار وأكواد التفعيل | كونكت تاق`,z=`دليل كافة باقات الإنترنت والمكالمات لشركة ${k}. الأسعار، الصلاحية، وأكواد التفعيل المباشرة.`,A=window.location.href,B=j.logo||'https://connecttag.org/assets/img/about/connect-tag-it-company.webp';document.title=y;document.getElementById('meta-description')?.setAttribute('content',z);document.getElementById('canonical-url')?.setAttribute('href',A);document.querySelector('meta[property="og:title"]')?.setAttribute('content',y);document.querySelector('meta[property="og:description"]')?.setAttribute('content',z);document.querySelector('meta[property="og:url"]')?.setAttribute('content',A);document.querySelector('meta[property="og:image"]')?.setAttribute('content',B);document.querySelector('meta[name="twitter:title"]')?.setAttribute('content',y);document.querySelector('meta[name="twitter:description"]')?.setAttribute('content',z);document.querySelector('meta[name="twitter:url"]')?.setAttribute('content',A);document.querySelector('meta[name="twitter:image"]')?.setAttribute('content',B);const C={"@context":"https://schema.org/","@type":"ItemList","name":`باقات ${k}`,"description":z,"itemListElement":o.slice(0,10).map((p,idx)=>({"@type":"ListItem","position":idx+1,"name":p.arTitle||p.title,"description":`السعر: ${p.price} ريال - ${p.duration||''}`}))},D=document.getElementById('schema-packages');if(D)D.textContent=JSON.stringify(C)}window.copyText=function(u){if(!u||u==='-')return;navigator.clipboard.writeText(u).then(()=>{CompanyApp.showToast('تم نسخ الكود: '+u)}).catch(()=>{CompanyApp.showToast('تعذر النسخ')})};function showError(n){d.innerHTML=`<div class="col-12 text-center py-5 text-danger font-weight-bold" style="grid-column: 1 / -1;"><i class="fa-solid fa-circle-exclamation fa-2x mb-3"></i><p>${n}</p></div>`}});